@startuml

class SensorController {
}

class Apartment {
  + address : string
  + email : string
}

class Inhabitant {
  + username : string
  + password : string
}

class Room {
  + description : string
}

abstract class Sensor {
  + vendor_id : string
  + description : string
  + unit : Unit
  + threshold : float
}

class TemperatureSensor extends Sensor {
  + min : float
  + max : float
}

class PowerSensor extends Sensor {
  + counter_reading : float
}

class MeasuredValue {
  + timestamp : datetime
  + value : float
}

enum Unit {
  CELSIUS
  WATT
}

class EMonitor {}

SensorController "1" -- "*" Apartment : manages
Apartment "1" -- "2..*" Room : consists of
Apartment "1" -- "*" Inhabitant : has
Inhabitant "0..1" -- "*" Sensor : configures
Room "1" -- "1..*" Sensor : contains
Sensor "1" -- "*" MeasuredValue : records
SensorController "1" -- "*" MeasuredValue : stores
EMonitor "1" -- "*" Sensor : checks thresholds
EMonitor "1" -- "0..1" Apartment : sends alerts to

@enduml

